use axum::response::Html;

pub async fn page() -> Html<String> {
    crate::ui::render(
        "Mon profil",
        "/account",
        r####"<div class="page-heading"><div class="eyebrow">Espace personnel</div><h1>Mon profil</h1><p class="lead">Quelques informations pour vous reconnaître dans les applications que vous choisissez d'utiliser.</p></div><div class="columns"><section class="panel"><h2>Informations publiques</h2><form id="profile-form"><label>Nom affiché<input name="display_name" maxlength="64" placeholder="Comment souhaitez-vous être appelé ?"></label><label>Photo de profil (URL HTTPS)<input name="avatar_url" type="url" placeholder="https://exemple.fr/avatar.jpg"></label><div class="hint">La photo reste hébergée à l'adresse indiquée et son chargement contacte cet hébergeur. L'adresse email et l'identifiant ne peuvent pas être modifiés ici.</div><button type="submit">Enregistrer les modifications</button></form><p id="profile-status" class="status" role="status" aria-live="polite"></p></section><aside class="stack"><section class="panel"><div id="avatar-fallback" aria-hidden="true" style="width:64px;height:64px;border-radius:20px;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center;font-size:1.5rem;font-weight:750;margin-bottom:17px">?</div><img id="avatar-preview" alt="Photo de profil" referrerpolicy="no-referrer" loading="lazy" hidden style="width:64px;height:64px;object-fit:cover;border-radius:20px;margin-bottom:17px"><h2>Mon identité</h2><p id="username" class="item-title">Chargement…</p><p id="email" class="muted"></p><p id="email-status" class="hint"></p></section><section class="panel"><h2>Applications connectées</h2><p class="muted">Gérez les services auxquels vous avez autorisé l'accès à vos informations.</p><a class="button secondary" href="/account/permissions">Voir mes autorisations</a></section></aside></div><script>
const form=document.getElementById('profile-form'),status=document.getElementById('profile-status');
async function refresh(){try{const response=await fetch('/account/profile/data',{credentials:'same-origin'});if(!response.ok){status.textContent='Connectez-vous depuis une application pour accéder à votre profil.';status.dataset.error='true';form.hidden=true;return;}const profile=await response.json();form.elements.display_name.value=profile.display_name||'';form.elements.avatar_url.value=profile.avatar_url||'';document.getElementById('username').textContent='@'+profile.username;document.getElementById('avatar-fallback').textContent=(profile.display_name||profile.username).trim().charAt(0).toUpperCase()||'?';const image=document.getElementById('avatar-preview'),placeholder=document.getElementById('avatar-fallback');image.hidden=true;placeholder.hidden=false;if(profile.avatar_url&&profile.avatar_url.startsWith('https://')){image.onload=()=>{image.hidden=false;placeholder.hidden=true;};image.onerror=()=>{image.hidden=true;placeholder.hidden=false;};image.src=profile.avatar_url;}document.getElementById('email').textContent=profile.email;document.getElementById('email-status').textContent=profile.email_verified?'Adresse vérifiée':'Adresse à vérifier';}catch{status.textContent='Impossible de charger le profil.';status.dataset.error='true';}}
form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;status.textContent='Enregistrement…';try{const data=Object.fromEntries(new FormData(form));const response=await fetch('/account/profile/data',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});status.textContent=response.ok?'Modifications enregistrées.':'Les informations sont invalides ou la session a expiré.';if(response.ok)await refresh();status.dataset.error=String(!response.ok);}catch{status.textContent='Erreur de connexion.';status.dataset.error='true';}finally{button.disabled=false;}});refresh();
</script>"####,
    )
}
